/// Issue #39: text that reaches a variable from a column — here a multi-line
/// JSON document — gets the response body's JSON matcher, not only equality.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn a_multi_line_extract_is_checked_as_json() {
    let _g = setup().await;
    let pool = AnyPool::connect(&test_dsn()).await.expect("connect");
    // A plain quoted literal may hold a raw newline on all three engines.
    sqlx::query(
        "INSERT INTO apibdd_it.companies (slug, name) \
         VALUES ('json-doc', '{\n  \"id\": 7,\n  \"tags\": [\"a\", \"b\"]\n}\n')",
    )
    .execute(&pool)
    .await
    .expect("insert the multi-line document");
    pool.close().await;
    let src = "\
Feature: extract
  Scenario: a multi-line column as JSON
    When I extract \"name\" from \"companies\" with \"slug: json-doc\" as \"doc\"
    Then variable \"doc\" should match \"\\n\"
    And variable \"doc\" should contain JSON:
      \"\"\"
      {\"id\": \"@variableType(int)\", \"tags\": [\"b\"]}
      \"\"\"
";
    let out = run_feature(src, &_g);
    assert!(out.status.success(), "{}", combined(&out));
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn sequence_and_builtin_function() {
    let _g = setup().await;
    // nextval increases — on the engines that have sequences at all. MySQL has
    // none, and the message it refuses with is a user-facing contract.
    let src = "\
Feature: routines
  Scenario: sequence
    Given I get next value of sequence \"apibdd_it.thing_seq\" as \"first\"
    And I get next value of sequence \"apibdd_it.thing_seq\" as \"second\"
    Then variable \"second\" should not be equal to \"<<first>>\"
";
    let out = run_feature(src, &_g);
    if engine() == Engine::MySql {
        assert!(!out.status.success(), "{}", combined(&out));
        assert!(
            combined(&out).contains("sequences are not supported on mysql"),
            "{}",
            combined(&out)
        );
    } else {
        assert!(out.status.success(), "{}", combined(&out));
    }

    // upper() is a builtin function taking a text argument — on every engine.
    let src = "\
Feature: routines
  Scenario: function
    When I call function \"upper\" with \"s: abc\" as \"up\"
    Then variable \"up\" should be equal to \"ABC\"
";
    let out = run_feature(src, &_g);
    assert!(out.status.success(), "{}", combined(&out));
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn eventual_database_assertion_observes_delayed_row() {
    let _g = setup().await;
    let without_polling = run_feature(
        "\
Feature: eventual database assertion
  Scenario: row appears asynchronously
    Then I should have \"companies\" with \"slug: delayed-company\"
",
        &_g,
    );
    assert!(
        !without_polling.status.success(),
        "assertion unexpectedly passed without polling: {}",
        combined(&without_polling)
    );

    // The debug line the assertion prints is dialect-specific: Postgres casts
    // its binds, MySQL/MariaDB use a bare `?`. It is the oneshot trigger below,
    // so a hardcoded one would not fail the test — it would hang to timeout.
    let probe = format!(
        "SQL: SELECT 1 FROM companies WHERE slug = {} LIMIT 1",
        match engine() {
            Engine::Postgres => "$1::text",
            Engine::MySql | Engine::MariaDb => "?",
        }
    );
    let delayed = AnyPool::connect(&test_dsn())
        .await
        .expect("connect delayed inserter");
    let (first_query, first_query_seen) = oneshot::channel();
    let inserter = tokio::spawn(async move {
        first_query_seen
            .await
            .expect("first assertion query signal dropped");
        tokio::time::sleep(Duration::from_millis(200)).await;
        sqlx::query("INSERT INTO apibdd_it.companies (slug) VALUES ('delayed-company')")
            .execute(&delayed)
            .await
            .expect("insert delayed company");
        delayed.close().await;
    });
    let mut child = feature_command(
        "\
Feature: eventual database assertion
  Scenario: row appears asynchronously
    Given I am in debug mode
    And I expect the next assertion to pass within \"2\" seconds, checking every \"50\" milliseconds
    Then I should have \"companies\" with \"slug: delayed-company\"
",
    )
    .stdout(Stdio::piped())
    .stderr(Stdio::piped())
    .spawn()
    .expect("start bddkit");
    let stdout = child.stdout.take().expect("capture bddkit stdout");
    let stderr = child.stderr.take().expect("capture bddkit stderr");
    let stdout_reader = std::thread::spawn(move || {
        let mut stdout_bytes = Vec::new();
        BufReader::new(stdout)
            .read_to_end(&mut stdout_bytes)
            .expect("read bddkit stdout");
        stdout_bytes
    });
    let probe_line = probe.clone();
    let reader = std::thread::spawn(move || {
        let mut stderr_bytes = Vec::new();
        let mut first_query = Some(first_query);
        for line in BufReader::new(stderr).split(b'\n') {
            let line = line.expect("read bddkit stderr");
            if line == probe_line.as_bytes()
                && let Some(first_query) = first_query.take()
            {
                first_query
                    .send(())
                    .expect("delayed inserter stopped early");
            }
            stderr_bytes.extend_from_slice(&line);
            stderr_bytes.push(b'\n');
        }
        stderr_bytes
    });
    let status = child.wait().expect("wait for bddkit");
    let with_polling = Output {
        status,
        stdout: stdout_reader.join().expect("stdout reader panicked"),
        stderr: reader.join().expect("stderr reader panicked"),
    };
    inserter.await.expect("delayed inserter panicked");
    let output = combined(&with_polling);
    assert!(with_polling.status.success(), "{output}");
    assert!(
        output.matches(probe.as_str()).count() >= 2,
        "polling assertion did not make an initial miss and retry: {output}"
    );
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn debug_mode_shows_query_duration_after_success_and_after_failure() {
    let _g = setup().await;
    let time_line = Regex::new(r"(?m)^TIME: \d+\.\d{2} ms$").unwrap();

    let ok_src = "\
Feature: query timing
  Scenario: successful insert
    Given I am in debug mode
    And I have \"companies\" with \"slug: timed-ok\"
";
    let ok_out = run_feature(ok_src, &_g);
    assert!(ok_out.status.success(), "{}", combined(&ok_out));
    let ok_output = combined(&ok_out);
    assert!(
        time_line.is_match(&ok_output),
        "expected a `TIME: ... ms` line after a successful query: {ok_output}"
    );

    // The second insert repeats the composite PK of the first — a duplicate
    // key error the server raises only after running the INSERT, so this
    // exercises the failure path (issue #54: timing must show up there too).
    let fail_src = "\
Feature: query timing
  Scenario: failing insert
    Given I am in debug mode
    And I have \"pair\" with \"a: 1, b: 1\"
    And I have \"pair\" with \"a: 1, b: 1\"
";
    let fail_out = run_feature(fail_src, &_g);
    assert!(
        !fail_out.status.success(),
        "expected a duplicate-key failure: {}",
        combined(&fail_out)
    );
    let fail_output = combined(&fail_out);
    assert!(
        time_line.is_match(&fail_output),
        "expected a `TIME: ... ms` line even when the query fails: {fail_output}"
    );
}
